    public interface SshBuilders {
        /**
         * SSH (camel-ssh)
         * Execute commands on remote hosts using SSH.
         * 
         * Category: file
         * Since: 2.10
         * Maven coordinates: org.apache.camel:camel-ssh
         * 
         * @return the dsl builder for the headers' name.
         */
        default SshHeaderNameBuilder ssh() {
            return SshHeaderNameBuilder.INSTANCE;
        }
        /**
         * SSH (camel-ssh)
         * Execute commands on remote hosts using SSH.
         * 
         * Category: file
         * Since: 2.10
         * Maven coordinates: org.apache.camel:camel-ssh
         * 
         * Syntax: <code>ssh:host:port</code>
         * 
         * Path parameter: host (required)
         * The host name or IP address of the SSH server. When the .ssh/config
         * file in the home directory of the user has an entry for this host,
         * the client connects to the HostName of that entry.
         * 
         * Path parameter: port
         * The port of the SSH server.
         * Default value: 22
         * 
         * @param path host:port
         * @return the dsl builder
         */
        default SshEndpointBuilder ssh(String path) {
            return SshEndpointBuilderFactory.endpointBuilder("ssh", path);
        }
        /**
         * SSH (camel-ssh)
         * Execute commands on remote hosts using SSH.
         * 
         * Category: file
         * Since: 2.10
         * Maven coordinates: org.apache.camel:camel-ssh
         * 
         * Syntax: <code>ssh:host:port</code>
         * 
         * Path parameter: host (required)
         * The host name or IP address of the SSH server. When the .ssh/config
         * file in the home directory of the user has an entry for this host,
         * the client connects to the HostName of that entry.
         * 
         * Path parameter: port
         * The port of the SSH server.
         * Default value: 22
         * 
         * @param componentName to use a custom component name for the endpoint
         * instead of the default name
         * @param path host:port
         * @return the dsl builder
         */
        default SshEndpointBuilder ssh(String componentName, String path) {
            return SshEndpointBuilderFactory.endpointBuilder(componentName, path);
        }

    }
    /**
     * The builder of headers' name for the SSH component.
     */
    public static class SshHeaderNameBuilder {
        /**
         * The internal instance of the builder used to access to all the
         * methods representing the name of headers.
         */
        public static final SshHeaderNameBuilder INSTANCE = new SshHeaderNameBuilder();

        /**
         * The user name that the producer logs in with, instead of the username
         * option. Used only when allowUsernameAndPasswordFromHeaders=true;
         * otherwise ignored. It applies to every kind of authentication: with
         * certResource or keyPairProvider, the configured key logs in as this
         * user.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code SshUsername}.
         */
        public String sshUsername() {
            return "CamelSshUsername";
        }
        /**
         * The password that the producer uses for password authentication,
         * instead of the password option. Used only when
         * allowUsernameAndPasswordFromHeaders=true; otherwise ignored. It is
         * not used when certResource or keyPairProvider is set.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code SshPassword}.
         */
        public String sshPassword() {
            return "CamelSshPassword";
        }
        /**
         * The standard error of the command, as an InputStream.
         * 
         * The option is a: {@code InputStream} type.
         * 
         * Group: common
         * 
         * @return the name of the header {@code SshStderr}.
         */
        public String sshStderr() {
            return "CamelSshStderr";
        }
        /**
         * The exit status of the command. By convention, a value other than 0
         * means that the command failed, but the exchange does not fail for it.
         * With channelType=shell it is usually null, as the shell is still
         * running when the output is read.
         * 
         * The option is a: {@code Integer} type.
         * 
         * Group: common
         * 
         * @return the name of the header {@code SshExitValue}.
         */
        public String sshExitValue() {
            return "CamelSshExitValue";
        }
    }
    static SshEndpointBuilder endpointBuilder(String componentName, String path) {
        class SshEndpointBuilderImpl extends AbstractEndpointBuilder implements SshEndpointBuilder, AdvancedSshEndpointBuilder {
            public SshEndpointBuilderImpl(String path) {
                super(componentName, path);
            }
        }
        return new SshEndpointBuilderImpl(path);
    }
